import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Suspense } from "react";
import { getCategories, getCategoryBySlug } from "@/lib/catalog";
import { Listing } from "@/components/store/Listing";

export async function generateStaticParams() {
  const categories = await getCategories();
  return categories.map((c) => ({ slug: c.slug }));
}

export async function generateMetadata({ params }: PageProps<"/category/[slug]">): Promise<Metadata> {
  const category = await getCategoryBySlug((await params).slug);
  return category ? { title: category.name, description: category.description ?? undefined } : {};
}

async function CategoryHeader({ slug }: { slug: string }) {
  const category = await getCategoryBySlug(slug);
  if (!category) notFound();
  return (
    <div className="mb-5">
      <nav className="mb-2 text-xs text-muted" aria-label="Breadcrumb">
        <Link href="/" className="hover:underline">Home</Link> ›{" "}
        {category.parent && <><Link href={`/category/${category.parent.slug}`} className="hover:underline">{category.parent.name}</Link> › </>}
        <span>{category.name}</span>
      </nav>
      <h1 className="font-display text-3xl font-semibold">{category.name}</h1>
      {category.description && <p className="mt-1 max-w-3xl text-sm text-muted">{category.description}</p>}
      {category.children.length > 0 && (
        <div className="mt-4 flex flex-wrap gap-2">
          {category.children.map((c) => (
            <Link key={c.id} href={`/category/${c.slug}`} className="rounded-full border border-line bg-white px-4 py-1.5 text-sm hover:border-brass">{c.name}</Link>
          ))}
        </div>
      )}
    </div>
  );
}

async function CategoryContent({ params, searchParams }: Pick<PageProps<"/category/[slug]">, "params" | "searchParams">) {
  const { slug } = await params;
  return (
    <>
      <Suspense fallback={<div className="mb-5 h-16" />}>
        <CategoryHeader slug={slug} />
      </Suspense>
      <Listing base={`/category/${slug}`} searchParams={searchParams} category={slug} />
    </>
  );
}

export default function CategoryPage({ params, searchParams }: PageProps<"/category/[slug]">) {
  return (
    <div className="container-x py-6">
      <Suspense fallback={<div className="h-96" />}>
        <CategoryContent params={params} searchParams={searchParams} />
      </Suspense>
    </div>
  );
}
